def _add_premium_badges(text):
    """Add premium emoji accents to common bot messages before conversion."""
    if not isinstance(text, str) or not text:
        return text

    # Use emoji characters already present in PREMIUM_EMOJI_IDS, so no
    # fabricated Telegram custom-emoji IDs are introduced.
    badges = [
        ("INFINITE X SELLER", "♾️"),
        ("Premium", "💎"),
        ("Balance", "💰"),
        ("Wallet", "💳"),
        ("Payment", "💵"),
        ("Order", "📦"),
        ("Key", "🔑"),
        ("Support", "🆘"),
        ("Admin", "👑"),
        ("Settings", "⚙️"),
        ("Success", "✅"),
        ("Error", "❌"),
        ("Processing", "⏳"),
        ("Loading", "🔄"),
        ("Buy", "🛒"),
        ("Price", "💲"),
        ("Users", "👥"),
        ("Statistics", "📊"),
        ("Products", "🛍️"),
    ]

    for word, emoji in badges:
        if word in text and emoji not in text:
            text = text.replace(word, f"{emoji} {word}", 1)

    return text

def _premiumize_html(text):
    """Convert supported normal emoji characters to Telegram custom emoji HTML."""
    if not isinstance(text, str) or not text:
        return text

    text = _add_premium_badges(text)

    # Longest first prevents partial matching of multi-codepoint emoji.
    for visible_emoji, emoji_id in sorted(
        PREMIUM_EMOJI_IDS.items(), key=lambda item: len(item[0]), reverse=True
    ):
        text = text.replace(
            visible_emoji,
            f'<tg-emoji emoji-id="{emoji_id}">{visible_emoji}</tg-emoji>'
        )
    return text


# Patch outgoing text methods so the existing bot code gets premium emojis
# without requiring every one of the hundreds of messages to be rewritten.
try:
    from telegram import Bot as _PremiumEmojiBot

    _original_send_message = _PremiumEmojiBot.send_message
    _original_edit_message_text = _PremiumEmojiBot.edit_message_text

    async def _premium_send_message(self, *args, **kwargs):
        text = kwargs.get("text")
        if text is None and len(args) >= 2:
            text = args[1]

        parse_mode = kwargs.get("parse_mode")
        if text and (parse_mode is None or str(parse_mode).upper() == "HTML"):
            new_text = _premiumize_html(text)
            if "text" in kwargs:
                kwargs["text"] = new_text
            elif len(args) >= 2:
                args = list(args)
                args[1] = new_text
                args = tuple(args)
            if parse_mode is None:
                kwargs["parse_mode"] = "HTML"

        return await _original_send_message(self, *args, **kwargs)

    async def _premium_edit_message_text(self, *args, **kwargs):
        text = kwargs.get("text")
        # Bot.edit_message_text(chat_id, message_id, text, ...)
        if text is None and len(args) >= 3:
            text = args[2]

        parse_mode = kwargs.get("parse_mode")
        if text and (parse_mode is None or str(parse_mode).upper() == "HTML"):
            new_text = _premiumize_html(text)
            if "text" in kwargs:
                kwargs["text"] = new_text
            elif len(args) >= 3:
                args = list(args)
                args[2] = new_text
                args = tuple(args)
            if parse_mode is None:
                kwargs["parse_mode"] = "HTML"

        return await _original_edit_message_text(self, *args, **kwargs)

    _PremiumEmojiBot.send_message = _premium_send_message
    _PremiumEmojiBot.edit_message_text = _premium_edit_message_text
except Exception:
    logger.exception("Premium emoji patch could not be installed")

# Premium emoji labels for reply/inline keyboard buttons.
def _premiumize_button_label(label):
    if not isinstance(label, str):
        return label
    return _premiumize_html(label)

try:
    from telegram import KeyboardButton as _PremiumKeyboardButton
    _original_keyboard_button_init = _PremiumKeyboardButton.__init__

    def _premium_keyboard_button_init(self, text, *args, **kwargs):
        text = _premiumize_button_label(text)
        return _original_keyboard_button_init(self, text, *args, **kwargs)

    _PremiumKeyboardButton.__init__ = _premium_keyboard_button_init
except Exception:
    logger.exception("Premium KeyboardButton patch could not be installed")




# ═══════════════════════════════════════════════════════════════════
# DATABASE LAYER
# ═══════════════════════════════════════════════════════════════════

class Database:
    def __init__(self, db_name: str):
        self.db_name = db_name
        self.init_db()
        self.seed_default_data()

    def _connect(self):
        conn = sqlite3.connect(self.db_name)
        conn.row_factory = sqlite3.Row
        return conn

    def init_db(self):
        conn = self._connect()
        c = conn.cursor()

        c.execute("""
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                telegram_id BIGINT UNIQUE NOT NULL,
                username TEXT,
                first_name TEXT,
                balance DECIMAL(10,2) DEFAULT 0,
                referral_code TEXT UNIQUE,
                referred_by INTEGER,
                referral_earnings DECIMAL(10,2) DEFAULT 0,
                total_orders INTEGER DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)

        c.execute("""
            CREATE TABLE IF NOT EXISTS products (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                group_name TEXT NOT NULL,
                description TEXT,
                image_file_id TEXT,
                status TEXT DEFAULT 'active',
                use_api INTEGER DEFAULT 1,
                api_version TEXT DEFAULT 'v2',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)

        c.execute("""
            CREATE TABLE IF NOT EXISTS product_plans (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                product_id INTEGER NOT NULL,
                plan_name TEXT NOT NULL,
                price DECIMAL(10,2) NOT NULL,
                api_hours INTEGER,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)

        c.execute("""
            CREATE TABLE IF NOT EXISTS orders (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                order_id TEXT UNIQUE NOT NULL,
                user_id INTEGER NOT NULL,
                product_id INTEGER NOT NULL,
                plan_id INTEGER NOT NULL,
                plan_name TEXT NOT NULL,
                price DECIMAL(10,2) NOT NULL,
                key_code TEXT,
                android_id TEXT,
                api_response TEXT,
                status TEXT DEFAULT 'completed',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)

        c.execute("""
            CREATE TABLE IF NOT EXISTS transactions (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER NOT NULL,
                type TEXT NOT NULL,
                amount DECIMAL(10,2) NOT NULL,
                utr TEXT,
                screenshot_file_id TEXT,
                status TEXT DEFAULT 'pending',
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)

        # Existing databases created by older versions need these columns.
        # ALTER TABLE is safe here because each column is added only if missing.
        for column, definition in [
            ("gateway_order_id", "TEXT"),
            ("gateway_payable_amount", "DECIMAL(10,2)"),
        ]:
            try:
                c.execute(f"ALTER TABLE transactions ADD COLUMN {column} {definition}")
            except sqlite3.OperationalError:
                pass

        c.execute("""
            CREATE TABLE IF NOT EXISTS coupons (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                code TEXT UNIQUE NOT NULL,
                type TEXT NOT NULL,
                value DECIMAL(10,2) NOT NULL,
                expiry_date TIMESTAMP,
                usage_limit INTEGER DEFAULT 1,
                used_count INTEGER DEFAULT 0,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            )
        """)

        conn.commit()
        conn.close()

    def seed_default_data(self):
        conn = self._connect()
        c = conn.cursor()
        try:
            c.execute("SELECT id FROM products WHERE name = ?", ("BALA MOD MENU",))
            if c.fetchone():
                conn.close()
                return
        except sqlite3.OperationalError:
            # Schema mismatch - recreate tables
            conn.close()
            self._recreate_tables()
            conn = self._connect()
            c = conn.cursor()

        c.execute("""
            INSERT INTO products (name, group_name, description, use_api, api_version)
            VALUES (?, ?, ?, ?, ?)
        """, (
            "BALA MOD MENU",
            "🎮 Gaming",
            "⚡ Fast Delivery\n🔒 Secure License Access\n💎 Reliable Service",
            1, "v2"
        ))
        product_id = c.lastrowid

        plans = [
            ("1 Hour", 25, 1), ("3 Hours", 55, 3), ("6 Hours", 95, 6),
            ("12 Hours", 190, 12), ("1 Day", 290, 24),
        ]
        for plan_name, price, hours in plans:
            c.execute("""
                INSERT INTO product_plans (product_id, plan_name, price, api_hours)
                VALUES (?, ?, ?, ?)
            """, (product_id, plan_name, price, hours))

        conn.commit()
        conn.close()

    def _recreate_tables(self):
        """Drop and recreate all tables (use with caution - deletes data)."""
        conn = self._connect()
        c = conn.cursor()
        c.execute("DROP TABLE IF EXISTS orders")
        c.execute("DROP TABLE IF EXISTS product_plans")
        c.execute("DROP TABLE IF EXISTS products")
        c.execute("DROP TABLE IF EXISTS transactions")
        c.execute("DROP TABLE IF EXISTS coupons")
        c.execute("DROP TABLE IF EXISTS users")
        conn.commit()
        conn.close()
        self.init_db()

