    def credit_gateway_transaction(self, tx_id: int, utr: Optional[str], verified_amount: float) -> Optional[Dict]:
        """Atomically credit a pending gateway transaction exactly once."""
        conn = self._connect()
        try:
            conn.execute("BEGIN IMMEDIATE")
            c = conn.cursor()
            c.execute("SELECT * FROM transactions WHERE id = ?", (tx_id,))
            tx = c.fetchone()
            if not tx or tx["status"] != "pending":
                conn.rollback()
                return None

            expected = float(tx["amount"])
            payable = float(tx["gateway_payable_amount"] or expected)
            got = float(verified_amount)

            # FamGateway documents a fractional payable_amount; verification
            # response can contain base amount, so accept either exact value.
            if abs(got - expected) > 0.02 and abs(got - payable) > 0.02:
                conn.rollback()
                raise ValueError(
                    f"Amount mismatch: expected {expected}/{payable}, received {got}"
                )

            c.execute(
                "UPDATE transactions SET status = 'approved', utr = COALESCE(?, utr) WHERE id = ? AND status = 'pending'",
                (utr, tx_id)
            )
            if c.rowcount != 1:
                conn.rollback()
                return None

            c.execute(
                "UPDATE users SET balance = balance + ? WHERE id = ?",
                (expected, tx["user_id"])
            )
            conn.commit()
            return dict(tx)
        except Exception:
            conn.rollback()
            raise
        finally:
            conn.close()

