async def start_command(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user = update.effective_user
    args = context.args

    referred_by = None
    if args and args[0].startswith("ref_"):
        ref_code = args[0].replace("ref_", "")
        ref_user = db.get_user_by_ref(ref_code)
        if ref_user and ref_user["telegram_id"] != user.id:
            referred_by = ref_user["id"]

    existing = db.get_user(user.id)
    if not existing:
        db.create_user(user.id, user.username, user.first_name, referred_by)

    welcome_text = f"""👋 Welcome to <b>{STORE_NAME}</b>

🛒 Your Trusted Gaming Services Store

⚡ Fast Delivery
🔒 Safe & Secure
💎 Premium Services

Please select an option below. 👇"""

    await update.message.reply_text(
        welcome_text,
        reply_markup=get_main_menu(user.id),
        parse_mode="HTML"
    )


