async def callback_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    query = update.callback_query
    await query.answer()
    data = query.data
    user_id = update.effective_user.id
    user = db.get_user(user_id)

    if not user:
        db.create_user(user_id, update.effective_user.username, update.effective_user.first_name)
        user = db.get_user(user_id)

    # ─── Navigation ───
    if data == "store":
        await show_store(query, user_id)
    elif data.startswith("store_cat:"):
        group = data.replace("store_cat:", "")
        await show_store_category(query, group)
    elif data.startswith("prod:"):
        product_id = int(data.replace("prod:", ""))
        await show_product(query, product_id)
    elif data.startswith("buy:"):
        parts = data.replace("buy:", "").split(":")
        product_id, plan_id = int(parts[0]), int(parts[1])
        await initiate_purchase(query, context, user, product_id, plan_id)
    elif data.startswith("confirm_buy:"):
        parts = data.replace("confirm_buy:", "").split(":")
        product_id, plan_id = int(parts[0]), int(parts[1])
        android_id = context.user_data.pop("android_id", None)
        await process_purchase(query, context, user, product_id, plan_id, android_id)
    elif data.startswith("check_payment:"):
        await check_payment_callback(query, context, data.split(":",1)[1])
    elif data == "wallet":
        await show_wallet(query, user)
    elif data == "add_balance":
        await ask_amount(query, context)
    elif data.startswith("amount:"):
        amt = data.replace("amount:", "")
        if amt == "custom":
            context.user_data["state"] = "await_amount"
            await query.edit_message_text(
                "💳 Enter amount to add (minimum ₹10):",
                reply_markup=get_back_button("wallet")
            )
        else:
            await show_payment_details(query, context, float(amt))
    elif data == "orders":
        await show_orders(query, user)
    elif data == "profile":
        await show_profile(query, user, context.bot.username)
    elif data == "support":
        await show_support(query)
    elif data == "redeem_coupon":
        context.user_data["state"] = "await_coupon"
        await query.edit_message_text(
            "🎁 Enter coupon code:",
            reply_markup=get_back_button("main")
        )
    elif data == "referral":
        await show_referral(query, user, context.bot.username)
    elif data.startswith("back:"):
        dest = data.replace("back:", "")
        if dest == "main":
            await safe_edit_message(
                query,
                f"👋 Welcome to <b>{STORE_NAME}</b>\n\nSelect an option:",
                reply_markup=get_main_menu(user_id),
                parse_mode="HTML"
            )
        elif dest == "store":
            await show_store(query, user_id)
        elif dest == "wallet":
            await show_wallet(query, user)
        elif dest == "orders":
            await show_orders(query, user)
        elif dest == "profile":
            await show_profile(query, user, context.bot.username)
        elif dest == "admin":
            await show_admin(query)

    elif data.startswith("prod_group:"):
        group = data.replace("prod_group:", "")
        context.user_data["prod_group"] = group
        context.user_data["state"] = "await_prod_plans"
        await query.edit_message_text(
            f"Step 3/4: Enter plans for <b>{context.user_data['prod_name']}</b>\n\n"
            f"Format (one per line):\n"
            f"<code>1 Hour = 25</code>\n"
            f"<code>3 Hours = 55</code>\n"
            f"<code>1 Day = 290</code>",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("❌ Cancel", callback_data="cancel_action", style="primary")]
            ]),
            parse_mode="HTML"
        )

    # ─── Admin Panel ───
    elif data == "admin":
        await show_admin(query)
    elif data == "admin_dashboard":
        await show_admin_dashboard(query)
    elif data == "admin_users":
        await show_admin_users(query)
    elif data == "admin_orders":
        await show_admin_orders(query)
    elif data == "admin_wallet_reqs":
        await show_admin_wallet_requests(query, context)
    elif data.startswith("approve_tx:"):
        tx_id = int(data.replace("approve_tx:", ""))
        await approve_transaction(query, context, tx_id)
    elif data.startswith("reject_tx:"):
        tx_id = int(data.replace("reject_tx:", ""))
        await reject_transaction(query, context, tx_id)
    elif data == "admin_products":
        await show_admin_products(query)
    elif data == "admin_add_product":
        await start_add_product(query, context)
    elif data.startswith("del_prod:"):
        product_id = int(data.replace("del_prod:", ""))
        await delete_product(query, product_id)
    elif data == "admin_coupons":
        await show_admin_coupons(query)
    elif data == "admin_add_coupon":
        await start_add_coupon(query, context)
    elif data == "admin_broadcast":
        await start_broadcast(query, context)
    elif data == "admin_add_balance":
        await start_admin_add_balance(query, context)
    elif data == "admin_deduct_balance":
        await start_admin_deduct_balance(query, context)
    elif data == "cancel_action":
        context.user_data.clear()
        await safe_edit_message(
            query,
            "❌ Action cancelled.",
            reply_markup=get_main_menu(user_id)
        )


