async def create_famgateway_order(amount: float, tx_id: int) -> Dict[str, Any]:
    if not FAMGATEWAY_API_KEY:
        raise RuntimeError("PAYMENT_API_KEY is not configured in Render.")

    params = {
        "api_key": FAMGATEWAY_API_KEY,
        "amount": f"{amount:.2f}",
    }
    if RENDER_PUBLIC_URL:
        params["webhook_url"] = f"{RENDER_PUBLIC_URL}{FAMGATEWAY_WEBHOOK_PATH}"

    # redirect_url is optional; the bot does not rely on it for confirmation.
    if RENDER_PUBLIC_URL:
        params["redirect_url"] = RENDER_PUBLIC_URL

    response = await asyncio.to_thread(
        requests.get, FAMGATEWAY_CREATE_URL, params=params, timeout=20
    )
    response.raise_for_status()
    payload = response.json()

    if payload.get("status") != "success":
        raise RuntimeError(payload.get("message", "FamGateway order creation failed."))

    data = payload.get("data") or {}
    order_id = data.get("order_id")
    checkout_url = data.get("checkout_url")
    qr_url = data.get("qr_url")
    payable_amount = float(data.get("payable_amount") or amount)

    if not order_id or not qr_url:
        raise RuntimeError("FamGateway response did not contain order_id/qr_url.")

    db.set_gateway_order(tx_id, order_id, payable_amount)
    return {
        "order_id": order_id,
        "checkout_url": checkout_url,
        "qr_url": qr_url,
        "payable_amount": payable_amount,
    }


async def show_payment_details(query, context, amount: float):
    if amount < 10:
        await query.answer("Minimum amount is ₹10!", show_alert=True); return
    user = db.get_user(query.from_user.id)
    if not user:
        await query.answer("Please use /start first.", show_alert=True); return
    tx_id = db.create_transaction(user["id"], amount)
    try: payment = await create_famgateway_order(amount, tx_id)
    except Exception as exc:
        db.reject_transaction(tx_id); await query.edit_message_text(f"❌ Payment gateway error.\n\n<code>{str(exc)[:300]}</code>", parse_mode="HTML", reply_markup=get_back_button("wallet")); return
    context.user_data.update({"recharge_amount":amount,"tx_id":tx_id,"gateway_order_id":payment["order_id"],"state":"await_gateway_payment"})
    caption=(f"💲 <b>ADD BALANCE</b>\n\n✔ Amount: {format_currency(amount)}\n💵 Pay exactly: <b>{format_currency(payment['payable_amount'])}</b>\n\n📱 Scan this QR and pay.\n🔊 Order: <code>{payment['order_id']}</code>\n\n⏳ After payment, tap <b>Check Payment</b>.")
    try: await query.message.delete()
    except Exception: pass
    await context.bot.send_photo(chat_id=query.message.chat_id, photo=payment["qr_url"], caption=caption, parse_mode="HTML", reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔄 Check Payment",callback_data=f"check_payment:{payment['order_id']}",style="primary")],[InlineKeyboardButton("❌ Cancel",callback_data="cancel_action",style="primary")]]))


async def show_payment_details_from_message(update, context, amount: float):
    if amount < 10: await update.message.reply_text("❌ Minimum amount is ₹10."); return
    user=db.get_user(update.effective_user.id)
    if not user: await update.message.reply_text("❌ Please use /start first."); return
    tx_id=db.create_transaction(user["id"],amount)
    try: payment=await create_famgateway_order(amount,tx_id)
    except Exception as exc:
        db.reject_transaction(tx_id); await update.message.reply_text(f"❌ Payment gateway error.\n\n<code>{str(exc)[:300]}</code>",parse_mode="HTML"); return
    context.user_data.update({"recharge_amount":amount,"tx_id":tx_id,"gateway_order_id":payment["order_id"],"state":"await_gateway_payment"})
    caption=(f"💳 <b>ADD BALANCE</b>\n\n💰 Amount: {format_currency(amount)}\n💵 Pay exactly: <b>{format_currency(payment['payable_amount'])}</b>\n\n📱 Scan this QR and pay.\n🆔 Order: <code>{payment['order_id']}</code>\n\n⏳ After payment, tap <b>Check Payment</b>.")
    await update.message.reply_photo(photo=payment["qr_url"],caption=caption,parse_mode="HTML",reply_markup=InlineKeyboardMarkup([[InlineKeyboardButton("🔄 Check Payment",callback_data=f"check_payment:{payment['order_id']}",style="primary")],[InlineKeyboardButton("❌ Cancel",callback_data="cancel_action",style="primary")]]))


