# ═══════════════════════════════════════════════════════════════════
# MESSAGE HANDLER
# ═══════════════════════════════════════════════════════════════════

async def message_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    user_id = update.effective_user.id
    user = db.get_user(user_id)

    if not user:
        db.create_user(user_id, update.effective_user.username, update.effective_user.first_name)
        user = db.get_user(user_id)

    state = context.user_data.get("state")
    text = update.message.text.strip() if update.message.text else ""

    # ─── Amount Input ───
    if state == "await_amount":
        try:
            amount = float(text)
            if amount < 10:
                await update.message.reply_text("❌ Minimum amount is ₹10.")
                return
            await show_payment_details_from_message(update, context, amount)
        except ValueError:
            await update.message.reply_text("❌ Please enter a valid number.")

    # ─── UTR Input ───
    elif state == "await_utr":
        tx_id = context.user_data.get("tx_id")
        amount = context.user_data.get("recharge_amount")

        if not tx_id:
            await update.message.reply_text("❌ Session expired. Start again.")
            return

        db.update_transaction(tx_id, utr=text)
        context.user_data.clear()

        await update.message.reply_text(
            f"✅ <b>Payment Submitted!</b>\n\n"
            f"💰 Amount: {format_currency(amount)}\n"
            f"🔢 UTR: <code>{text}</code>\n\n"
            f"⏳ Your payment will be verified within 10-30 minutes.",
            reply_markup=get_main_menu(user_id),
            parse_mode="HTML"
        )

        await context.bot.send_message(
            chat_id=ADMIN_ID,
            text=f"💳 <b>NEW PAYMENT REQUEST</b>\n\n"
                 f"👤 User: @{user.get('username') or user_id}\n"
                 f"🆔 User ID: <code>{user_id}</code>\n"
                 f"💰 Amount: {format_currency(amount)}\n"
                 f"🔢 UTR: <code>{text}</code>\n\n"
                 f"Check admin panel to approve.",
            parse_mode="HTML"
        )

    # ─── Android ID Input ───
    elif state == "await_android_id":
        pending = context.user_data.get("pending_purchase")
        if not pending:
            await update.message.reply_text("❌ Session expired.")
            return

        android_id = text
        context.user_data.pop("state", None)
        context.user_data.pop("pending_purchase", None)

        product = db.get_product(pending["product_id"])
        plan = db.get_plan(pending["plan_id"])
        balance = float(user["balance"])
        price = float(plan["price"])

        await update.message.reply_text(
            f"📦 <b>ORDER SUMMARY</b>\n\n"
            f"🎮 Product: {product['name']}\n"
            f"📋 Plan: {plan['plan_name']}\n"
            f"📱 Android ID: <code>{android_id}</code>\n"
            f"💰 Price: {format_currency(price)}\n"
            f"💳 Balance After: {format_currency(balance - price)}\n\n"
            f"Do you want to confirm?",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ Confirm", callback_data=f"confirm_buy:{pending['product_id']}:{pending['plan_id']}", style="primary")],
                [InlineKeyboardButton("❌ Cancel", callback_data="cancel_action", style="primary")]
            ]),
            parse_mode="HTML"
        )
        context.user_data["android_id"] = android_id

    # ─── Coupon Redeem ───
    elif state == "await_coupon":
        context.user_data.pop("state", None)
        coupon = db.get_coupon(text)

        if not coupon:
            await update.message.reply_text(
                "❌ Invalid or expired coupon code.",
                reply_markup=get_main_menu(user_id)
            )
            return

        if coupon["used_count"] >= coupon["usage_limit"]:
            await update.message.reply_text(
                "❌ This coupon has reached its usage limit.",
                reply_markup=get_main_menu(user_id)
            )
            return

        db.use_coupon(text)

        if coupon["type"] == "BALANCE":
            db.update_balance(user_id, float(coupon["value"]))
            await update.message.reply_text(
                f"🎁 <b>Coupon Redeemed!</b>\n\n"
                f"💰 {format_currency(coupon['value'])} added to your wallet!",
                reply_markup=get_main_menu(user_id),
                parse_mode="HTML"
            )
        else:
            await update.message.reply_text(
                f"🎁 Coupon <b>{coupon['code']}</b> redeemed!\n"
                f"Use it during checkout for {coupon['type']} discount.",
                reply_markup=get_main_menu(user_id),
                parse_mode="HTML"
            )

    # ─── Add Product Flow ───
    elif state == "await_prod_name":
        context.user_data["prod_name"] = text
        context.user_data["state"] = "await_prod_group"

        buttons = [
            [InlineKeyboardButton("🎮 Gaming", callback_data="prod_group:🎮 Gaming", style="primary")],
            [InlineKeyboardButton("💻 Software", callback_data="prod_group:💻 Software", style="primary")],
            [InlineKeyboardButton("🎁 Gift Cards", callback_data="prod_group:🎁 Gift Cards", style="primary")],
            [InlineKeyboardButton("📺 Subscriptions", callback_data="prod_group:📺 Subscriptions", style="primary")],
            [InlineKeyboardButton("🔐 License Keys", callback_data="prod_group:🔐 License Keys", style="primary")],
            [InlineKeyboardButton("🧩 Other", callback_data="prod_group:🧩 Other", style="primary")],
            [InlineKeyboardButton("❌ Cancel", callback_data="cancel_action", style="primary")]
        ]
        await update.message.reply_text(
            "Step 2/4: Select Product Group",
            reply_markup=InlineKeyboardMarkup(buttons)
        )

    elif state == "await_prod_plans":
        try:
            plans = []
            for line in text.split("\n"):
                if "=" in line:
                    name, price = line.split("=", 1)
                    plans.append((name.strip(), float(price.strip())))

            if not plans:
                await update.message.reply_text("❌ Invalid format. Use: Plan Name = Price")
                return

            context.user_data["prod_plans"] = plans
            context.user_data["state"] = "await_prod_desc"
            await update.message.reply_text(
                "Step 4/4: Send Product Description (or send '-' to skip):",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("❌ Cancel", callback_data="cancel_action", style="primary")]
                ])
            )
        except Exception as e:
            await update.message.reply_text(f"❌ Error parsing plans: {e}")

    elif state == "await_prod_desc":
        desc = text if text != "-" else ""
        context.user_data["prod_desc"] = desc

        name = context.user_data["prod_name"]
        group = context.user_data["prod_group"]
        plans = context.user_data["prod_plans"]

        product_id = db.create_product(name, group, desc)
        for plan_name, price in plans:
            api_hours = API_HOURS_MAP.get(plan_name)
            db.add_product_plan(product_id, plan_name, price, api_hours)

        context.user_data.clear()
        await update.message.reply_text(
            f"✅ Product <b>{name}</b> created with {len(plans)} plans!",
            reply_markup=get_main_menu(user_id),
            parse_mode="HTML"
        )

    # ─── Add Coupon ───
    elif state == "await_coupon_code":
        context.user_data.pop("state", None)
        try:
            parts = text.split()
            if len(parts) < 3:
                raise ValueError("Invalid format")

            code = parts[0].upper()
            type_ = parts[1].upper()
            value = float(parts[2])
            days = int(parts[3]) if len(parts) > 3 else 30
            limit = int(parts[4]) if len(parts) > 4 else 1

            db.create_coupon(code, type_, value, days, limit)
            await update.message.reply_text(
                f"✅ Coupon <b>{code}</b> created!",
                reply_markup=get_main_menu(user_id),
                parse_mode="HTML"
            )
        except Exception as e:
            await update.message.reply_text(
                f"❌ Error: {e}\nFormat: CODE TYPE VALUE DAYS LIMIT",
                reply_markup=get_main_menu(user_id)
            )

    # ─── Broadcast ───
    elif state == "await_broadcast":
        context.user_data.pop("state", None)
        users = db.get_all_users(limit=10000)
        sent = 0
        failed = 0

        await update.message.reply_text("📢 Broadcasting... Please wait.")

        for u in users:
            try:
                await context.bot.send_message(
                    chat_id=u["telegram_id"],
                    text=f"📢 <b>Announcement from {STORE_NAME}</b>\n\n{text}",
                    parse_mode="HTML"
                )
                sent += 1
                await asyncio.sleep(0.05)
            except Exception:
                failed += 1

        await update.message.reply_text(
            f"✅ Broadcast complete!\nSent: {sent}\nFailed: {failed}",
            reply_markup=get_main_menu(user_id)
        )

    # ─── Admin Add Balance ───
    elif state == "await_admin_user_id":
        try:
            target_id = int(text)
            context.user_data["target_user_id"] = target_id
            context.user_data["state"] = "await_admin_amount"
            await update.message.reply_text(
                "Enter amount to add:",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("❌ Cancel", callback_data="cancel_action", style="primary")]
                ])
            )
        except ValueError:
            await update.message.reply_text("❌ Please enter a valid numeric User ID.")

    elif state == "await_admin_amount":
        try:
            amount = float(text)
            target_id = context.user_data.get("target_user_id")

            db.update_balance(target_id, amount)
            context.user_data.clear()

            await update.message.reply_text(
                f"✅ Added {format_currency(amount)} to user <code>{target_id}</code>",
                reply_markup=get_main_menu(user_id),
                parse_mode="HTML"
            )

            try:
                await context.bot.send_message(
                    chat_id=target_id,
                    text=f"🎉 <b>Balance Added!</b>\n\n"
                         f"💰 {format_currency(amount)} has been added to your wallet by admin.",
                    parse_mode="HTML"
                )
            except Exception:
                pass
        except ValueError:
            await update.message.reply_text("❌ Please enter a valid amount.")

    # ─── Admin Deduct Balance ───
    elif state == "await_deduct_user_id":
        try:
            target_id = int(text)
            context.user_data["target_deduct_user_id"] = target_id
            context.user_data["state"] = "await_deduct_amount"
            await update.message.reply_text(
                "Enter amount to deduct:",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("❌ Cancel", callback_data="cancel_action", style="primary")]
                ])
            )
        except ValueError:
            await update.message.reply_text("❌ Please enter a valid numeric User ID.")

    elif state == "await_deduct_amount":
        try:
            amount = float(text)
            if amount <= 0:
                await update.message.reply_text("❌ Amount must be greater than 0.")
                return

            target_id = context.user_data.get("target_deduct_user_id")
            target_user = db.get_user(target_id)

            if not target_user:
                await update.message.reply_text("❌ User not found in database.")
                context.user_data.clear()
                return

            current_balance = float(target_user["balance"])
            if current_balance < amount:
                await update.message.reply_text(
                    f"❌ User has insufficient balance.\n\n"
                    f"💰 Current Balance: {format_currency(current_balance)}\n"
                    f"➖ Deduct Amount: {format_currency(amount)}",
                    reply_markup=get_main_menu(user_id)
                )
                context.user_data.clear()
                return

            db.update_balance(target_id, -amount)
            context.user_data.clear()

            await update.message.reply_text(
                f"✅ <b>Balance Deducted</b>\n\n"
                f"👤 User ID: <code>{target_id}</code>\n"
                f"➖ Deducted: {format_currency(amount)}\n"
                f"💰 New Balance: {format_currency(current_balance - amount)}",
                reply_markup=get_main_menu(user_id),
                parse_mode="HTML"
            )

            try:
                await context.bot.send_message(
                    chat_id=target_id,
                    text=f"⚠️ <b>Balance Deducted by Admin</b>\n\n"
                         f"➖ Amount: {format_currency(amount)}\n"
                         f"💰 New Balance: {format_currency(current_balance - amount)}\n\n"
                         f"If you think this is a mistake, contact {SUPPORT_USERNAME}.",
                    parse_mode="HTML"
                )
            except Exception as e:
                logger.error(f"Failed to notify user {target_id}: {e}")
        except ValueError:
            await update.message.reply_text("❌ Please enter a valid amount.")

    else:
        await update.message.reply_text(
            "👋 Welcome! Use the menu below:",
            reply_markup=get_main_menu(user_id)
        )


# ═══════════════════════════════════════════════════════════════════
# PHOTO HANDLER (Screenshot Upload)
# ═══════════════════════════════════════════════════════════════════

async def photo_handler(update: Update, context: ContextTypes.DEFAULT_TYPE):
    state = context.user_data.get("state")
    if state == "await_gateway_payment":
        await update.message.reply_text(
            "ℹ️ This payment is handled automatically. Please use the <b>Pay Now</b> button and wait for confirmation.",
            parse_mode="HTML"
        )
        return

    # Keep the old manual screenshot flow available for any legacy transaction.
    if state != "await_screenshot":
        await update.message.reply_text("❌ I wasn't expecting a photo. Please use the menu.")
        return

    amount = context.user_data.get("recharge_amount", 0)
    photo_file = update.message.photo[-1]
    file_id = photo_file.file_id
    user = db.get_user(update.effective_user.id)
    tx_id = db.create_transaction(user["id"], amount)
    db.update_transaction(tx_id, screenshot=file_id)
    context.user_data["tx_id"] = tx_id
    context.user_data["state"] = "await_utr"

    await update.message.reply_text(
        "✅ Screenshot received!\n\nPlease enter the UTR/Transaction Reference Number:",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("❌ Cancel", callback_data="cancel_action", style="primary")]
        ])
    )



async def check_payment_callback(query, context, order_id: str):
    if not FAMGATEWAY_API_KEY:
        await query.answer("Payment gateway is not configured.", show_alert=True); return
    try:
        r=await asyncio.to_thread(requests.get,FAMGATEWAY_VERIFY_URL,params={"api_key":FAMGATEWAY_API_KEY,"order_id":order_id},timeout=20); r.raise_for_status(); result=r.json()
        if result.get("status")!="success":
            await query.answer("⏳ Payment not confirmed yet. Please wait and check again.",show_alert=True); return
        data=result.get("data") or {}
        tx=db.get_transaction_by_gateway_order(order_id)
        if not tx: await query.answer("❌ Payment order not found.",show_alert=True); return
        credited=db.credit_gateway_transaction(tx["id"],utr=data.get("utr"),verified_amount=float(data.get("payable_amount") or data.get("amount") or 0))
        if credited:
            user=db.get_user_by_id(credited["user_id"])
            if user: await context.bot.send_message(chat_id=user["telegram_id"],text=f"✅ <b>PAYMENT APPROVED</b>\n\n💰 Added: {format_currency(credited['amount'])}\n🔢 UTR: <code>{data.get('utr') or 'N/A'}</code>\n💳 Order: <code>{order_id}</code>\n\nYour wallet balance has been updated automatically.",parse_mode="HTML",reply_markup=get_main_menu(user["telegram_id"]))
        await query.answer("✅ Payment verified! Wallet updated.",show_alert=True)
        try: await query.message.delete()
        except Exception: pass
    except Exception:
        logger.exception("Manual payment verification failed")
        await query.answer("⚠️ Verification failed temporarily. Please try again.",show_alert=True)


# ═══════════════════════════════════════════════════════════════════
# FAMGATEWAY WEBHOOK SERVER
# Render needs a public HTTP listener for webhook delivery.
# ═══════════════════════════════════════════════════════════════════

TELEGRAM_LOOP = None
TELEGRAM_APPLICATION = None


async def process_famgateway_webhook(raw_body: bytes, signature: str):
    if not FAMGATEWAY_API_KEY:
        raise RuntimeError("PAYMENT_API_KEY is not configured.")

    expected = hmac.new(
        FAMGATEWAY_API_KEY.encode("utf-8"),
        raw_body,
        hashlib.sha256
    ).hexdigest()

    if not signature or not hmac.compare_digest(expected, signature):
        raise PermissionError("Invalid FamGateway webhook signature.")

    event = json.loads(raw_body.decode("utf-8"))
    if event.get("event") != "payment.success":
        return

    order_id = event.get("order_id") or (event.get("data") or {}).get("order_id")
    if not order_id:
        raise ValueError("Webhook missing order_id.")

    # Verify against FamGateway's server before crediting balance.
    verify = await asyncio.to_thread(
        requests.get,
        FAMGATEWAY_VERIFY_URL,
        params={"api_key": FAMGATEWAY_API_KEY, "order_id": order_id},
        timeout=20
    )
    verify.raise_for_status()
    result = verify.json()

    if result.get("status") != "success":
        raise ValueError(f"Gateway verification failed: {result.get('message', result.get('status'))}")

    data = result.get("data") or {}
    verified_order_id = data.get("order_id")
    verified_amount = float(data.get("payable_amount") or data.get("amount") or 0)
    utr = data.get("utr")

    if verified_order_id != order_id:
        raise ValueError("Verified order_id mismatch.")

    tx = db.get_transaction_by_gateway_order(order_id)
    if not tx:
        raise ValueError("Unknown gateway order_id.")

    credited = db.credit_gateway_transaction(
        tx["id"], utr=utr, verified_amount=verified_amount
    )
    if not credited:
        logger.info("Gateway order %s already processed or no longer pending.", order_id)
        return

    user = db.get_user_by_id(credited["user_id"])
    if user:
        try:
            await TELEGRAM_APPLICATION.bot.send_message(
                chat_id=user["telegram_id"],
                text=(
                    "✅ <b>PAYMENT APPROVED</b>\n\n"
                    f"💰 Added: {format_currency(credited['amount'])}\n"
                    f"🔢 UTR: <code>{utr or 'N/A'}</code>\n"
                    f"💳 Order: <code>{order_id}</code>\n\n"
                    "Your wallet balance has been updated automatically."
                ),
                parse_mode="HTML",
                reply_markup=get_main_menu(user["telegram_id"])
            )
        except Exception as exc:
            logger.error("Could not notify user after auto payment: %s", exc)


class FamGatewayWebhookHandler(BaseHTTPRequestHandler):
    def log_message(self, fmt, *args):
        logger.info("Webhook server: " + fmt, *args)

    def _send(self, code: int, body: str):
        body_bytes = body.encode("utf-8")
        self.send_response(code)
        self.send_header("Content-Type", "text/plain; charset=utf-8")
        self.send_header("Content-Length", str(len(body_bytes)))
        self.end_headers()
        self.wfile.write(body_bytes)

    def do_GET(self):
        path = urlparse(self.path).path
        if path == "/health":
            self._send(200, "OK")
        elif path == FAMGATEWAY_WEBHOOK_PATH:
            self._send(200, "FamGateway webhook endpoint is ready.")
        else:
            self._send(404, "Not found")

    def do_POST(self):
        path = urlparse(self.path).path
        if path != FAMGATEWAY_WEBHOOK_PATH:
            self._send(404, "Not found")
            return

        try:
            length = int(self.headers.get("Content-Length", "0"))
            raw = self.rfile.read(length)
            signature = self.headers.get("X-FamGateway-Signature", "")
            if TELEGRAM_LOOP is None or TELEGRAM_APPLICATION is None:
                raise RuntimeError("Telegram application is not ready.")

            future = asyncio.run_coroutine_threadsafe(
                process_famgateway_webhook(raw, signature),
                TELEGRAM_LOOP
            )
            future.result(timeout=25)
            self._send(200, "OK")
        except PermissionError as exc:
            logger.warning("Rejected webhook: %s", exc)
            self._send(401, "Invalid signature")
        except Exception as exc:
            logger.exception("Webhook processing failed")
            self._send(500, "Webhook processing failed")


def start_webhook_server():
    server = ThreadingHTTPServer(("0.0.0.0", RENDER_PORT), FamGatewayWebhookHandler)
    logger.info(
        "🌐 HTTP server listening on 0.0.0.0:%s; webhook path=%s",
        RENDER_PORT, FAMGATEWAY_WEBHOOK_PATH
    )
    server.serve_forever()


async def post_init(application):
    global TELEGRAM_LOOP, TELEGRAM_APPLICATION
    TELEGRAM_LOOP = asyncio.get_running_loop()
    TELEGRAM_APPLICATION = application
    import threading
    threading.Thread(target=start_webhook_server, daemon=True, name="famgateway-webhook").start()


# ═══════════════════════════════════════════════════════════════════
# MAIN
# ═══════════════════════════════════════════════════════════════════

def main():
    application = Application.builder().token(BOT_TOKEN).post_init(post_init).build()

    application.add_handler(CommandHandler("start", start_command))
    application.add_handler(CommandHandler("help", help_command))

    application.add_handler(CallbackQueryHandler(callback_handler))

    application.add_handler(MessageHandler(filters.PHOTO, photo_handler))
    application.add_handler(MessageHandler(filters.TEXT & ~filters.COMMAND, message_handler))

    logger.info(f"🚀 {STORE_NAME} Bot started!")
    application.run_polling(allowed_updates=Update.ALL_TYPES)


if __name__ == "__main__":
    main()
